#include "exotic/cognition/agent_store.hpp"
#include "exotic/cognition/intention.hpp"
#include <cassert>
#include <cstdio>
int main(){const char*db="intention_test.sqlite";std::remove(db);{exotic::cognition::AgentStore store(db);store.initialize();exotic::cognition::IntentionManager m(store);exotic::cognition::VolitionDecision d{exotic::cognition::VolitionOutcome::Choose,"inspect","Inspect because evidence is incomplete",0.72};auto c=m.record_choice("Investigate anomaly",d,"1000");auto i=m.propose_intention(c,0.7,"Worth considering, not yet a commitment");assert(i.state=="tentative");assert(i.created_at=="1000");assert(i.updated_at=="1000");assert(m.stale(1100,50).size()==1);assert(m.commit(i.id,"I choose to make this durable"));assert(m.intentions().front().state=="committed");assert(m.transitions(i.id).size()==1);assert(m.complete(i.id,"The intended outcome was achieved"));assert(m.intentions().front().state=="completed");assert(m.transitions(i.id).size()==2);assert(m.transitions(i.id).back().to_state=="completed");assert(!m.suspend(i.id,"Completed work cannot be silently reopened"));assert(m.stale(999999,1).empty());exotic::cognition::VolitionDecision d2{exotic::cognition::VolitionOutcome::DoNothing,"","No option is worth committing to",0.1};auto c2=m.record_choice("Same anomaly",d2,"1001",c.id);assert(c2.supersedes==c.id);assert(m.choices().size()==2);assert(m.intentions().size()==1);}std::remove(db);std::remove("intention_test.sqlite-wal");std::remove("intention_test.sqlite-shm");return 0;}
